// THE CONTRACT, IN A BROWSER, FROM THE SAME SOURCE FILES NODE RUNS.
//
// The importer is a browser surface and the contract is a set of CommonJS
// modules. There are two ways to bridge that and only one of them is honest:
// re-implement the rules in the UI, or run the modules. A re-implementation is
// a second set of rules that agrees with the first until the day it does not,
// and the day it does not is the day a package validates in the importer and is
// refused everywhere else. So this wraps the real files.
//
// Nothing here transforms the sources. Each is wrapped in the smallest possible
// CommonJS shim and concatenated. If a module would not run in Node it does not
// run here either, and the reverse.
//
// WHAT IS DELIBERATELY NOT AVAILABLE. fs, path and libraries.js resolve to stubs
// that THROW when touched. The first two are Node's, and libraries.js walks the
// content files to build the manifest, which is design-time work. The browser is
// given the GENERATED manifest and registries instead. A stub that threw quietly
// would let the importer fall back to some emptier answer, so these say what was
// reached for and stop.
//
// The CLI blocks at the foot of validate.js, admit.js and publish.js are inert
// rather than stripped: require.main is undefined here, so `require.main ===
// module` is false and the block never runs. Stripping them would mean editing
// the source on the way in, which is the thing this file exists not to do.
const fs = require("fs");
const path = require("path");

// Order matters only in that every module must be defined before the entry
// point runs. They are required lazily by the shim, so this is just the set.
const MODULES = ["fields.js", "capabilities.js", "directives.js", "generate.js",
                 "resolve.js", "validate.js", "admit.js", "publish.js", "diagnostics.js", "store.js"];

function bundle(root) {
  const dir = path.join(root, "tools", "contract");
  const parts = [];
  MODULES.forEach(name => {
    const src = fs.readFileSync(path.join(dir, name), "utf8");
    // The same rule build.js applies to every inlined script. A source that can
    // close the tag it is inside is not inlinable, and finding that out in a
    // browser is finding out too late.
    if (/<\/script/i.test(src))
      throw new Error(name + " contains a literal </script and cannot be inlined");
    // A module reaching for the network or a subprocess is not a contract
    // module. Checked here because this is the point where it would reach a
    // browser, and the check is cheap.
    if (/require\("(?:http|https|net|child_process|worker_threads|vm)"\)/.test(src))
      throw new Error(name + " opens a network or a process and may not be bundled");
    parts.push("__defs[" + JSON.stringify("./" + name) + "] = function (module, exports, require) {\n" +
      src + "\n};");
  });

  return [
    "// GENERATED by tools/contract/bundle.js from tools/contract/*.js. Do not edit.",
    "// Every rule the importer applies is the rule in those files, running here.",
    "(function () {",
    '  "use strict";',
    "  var __defs = {}, __cache = {};",
    "  function __stub(what, why) {",
    "    return new Proxy({}, { get: function (t, k) {",
    "      throw new Error('the importer reached for ' + what + '.' + String(k) + ', which is not available in a browser. ' + why);",
    "    } });",
    "  }",
    "  function __require(id) {",
    "    if (id === 'fs') return __stub('fs', 'The importer is given file contents by the page, and never reads a path.');",
    "    if (id === 'path') return __stub('path', 'There are no paths here.');",
    "    if (id === './libraries.js') return __stub('libraries',",
    "      'It walks the content files to build the manifest, which is design time work. The generated manifest and registries are supplied instead.');",
    "    if (__cache[id]) return __cache[id].exports;",
    "    if (!__defs[id]) throw new Error('no such module in the contract bundle: ' + id);",
    "    var m = { exports: {} };",
    "    __cache[id] = m;",
    "    __defs[id](m, m.exports, __require);",
    "    return m.exports;",
    "  }",
    "",
    parts.join("\n"),
    "",
    "  var validate = __require('./validate.js');",
    "  var resolve = __require('./resolve.js');",
    "  var admit = __require('./admit.js');",
    "  var publish = __require('./publish.js');",
    "  var capabilities = __require('./capabilities.js');",
    "  var fields = __require('./fields.js');",
    "  var generate = __require('./generate.js');",
    "  var diagnostics = __require('./diagnostics.js');",
    "  var store = __require('./store.js');",
    "  // THE ADAPTER CHOOSES THE BACKEND, not the page. importer.js never names",
    "  // localStorage, which is what lets the build refuse an importer that has a",
    "  // write path of its own: there is exactly one, and it is here.",
    "  var backend = null;",
    "  try { window.localStorage.setItem('marginal.import.probe', '1');",
    "        window.localStorage.removeItem('marginal.import.probe');",
    "        backend = store.localStorageBackend(window.localStorage); }",
    "  catch (e) { backend = store.memoryBackend(); backend.name = 'memory (storage unavailable: ' + e.name + ')'; }",
    "  window.MarginalContract = {",
    "    validate: validate.validate, libraryReadiness: validate.libraryReadiness,",
    "    resolve: resolve.resolve, storable: resolve.storable, carriedPaths: resolve.carriedPaths,",
    "    admit: admit.admit, plan: admit.plan, writes: admit.writes, fingerprint: admit.fingerprint, paths: admit.paths,",
    "    apply: publish.apply, destination: publish.destination, registryOf: publish.registryOf,",
    "    OUTCOME: publish.OUTCOME, STALE: publish.STALE,",
    "    CAPABILITIES: capabilities.RULES ? Object.keys(capabilities.RULES) : [],",
    "    contractVersion: generate.CONTRACT_VERSION,",
    "    FIELDS: fields.FIELDS,",
    "    groupErrors: diagnostics.groupErrors, groupOf: diagnostics.groupOf,",
    "    store: store.createStore(backend),",
    "    memoryStore: function () { return store.createStore(store.memoryBackend()); },",
    "    failingStore: function (id) { return store.createStore(store.failingBackend(backend, id)); },",
    "  };",
    "})();",
    "",
  ].join("\n");
}

// THE STUDENT SIDE. Two modules only: the store, so imported questions are read
// through the same adapter that wrote them, and the runtime adapter that turns a
// stored package into a question the app can serve.
//
// Deliberately NOT the validator, the resolver or admission. A student surface
// has nothing to decide about a package: it was validated and admitted before it
// was ever written, and re-deciding here would be a second opinion that can
// disagree with the first. It reads what is there.
const STUDENT_MODULES = ["store.js", "runtime.js"];

function studentBundle(root) {
  const dir = path.join(root, "tools", "contract");
  const parts = STUDENT_MODULES.map(name => {
    const src = fs.readFileSync(path.join(dir, name), "utf8");
    if (/<\/script/i.test(src)) throw new Error(name + " contains a literal </script and cannot be inlined");
    return "__defs[" + JSON.stringify("./" + name) + "] = function (module, exports, require) {\n" + src + "\n};";
  });
  return [
    "// GENERATED by tools/contract/bundle.js from tools/contract/store.js and",
    "// tools/contract/runtime.js. Do not edit. The student app reads imported",
    "// questions through the same adapter the importer wrote them with.",
    "(function () {",
    '  "use strict";',
    "  var __defs = {}, __cache = {};",
    "  function __require(id) {",
    "    if (__cache[id]) return __cache[id].exports;",
    "    if (!__defs[id]) throw new Error('no such module in the student bundle: ' + id);",
    "    var m = { exports: {} };",
    "    __cache[id] = m;",
    "    __defs[id](m, m.exports, __require);",
    "    return m.exports;",
    "  }",
    "",
    parts.join("\n"),
    "",
    "  var store = __require('./store.js');",
    "  var runtime = __require('./runtime.js');",
    "  // Storage may be unavailable, and a student whose browser blocks it must",
    "  // still get the questions that shipped. It degrades to holding nothing,",
    "  // never to failing to load.",
    "  var backend = null;",
    "  try { window.localStorage.getItem('marginal.import.index');",
    "        backend = store.localStorageBackend(window.localStorage); }",
    "  catch (e) { backend = store.memoryBackend(); }",
    "  var S = store.createStore(backend);",
    "  var TOPICS = window.MarginalTopics || {};",
    "  window.MarginalImports = {",
    "    load: function () { try { return S.load(); } catch (e) { return { questions: {}, shared: {}, broken: [{ key: null, why: String(e && e.message || e) }] }; } },",
    "    merge: function (subjects) { return runtime.mergeSubjects(subjects, window.MarginalImports.load(), { topics: TOPICS }); },",
    "    toRuntimeQuestion: function (doc) { return runtime.toRuntimeQuestion(doc, { topics: TOPICS }); },",
    "    directiveId: runtime.directiveId, directiveLabel: runtime.directiveLabel, topicId: runtime.topicId,",
    "    backend: backend.name,",
    "  };",
    "})();",
    "",
  ].join("\n");
}

module.exports = { bundle, studentBundle, MODULES, STUDENT_MODULES };

if (require.main === module) {
  process.stdout.write(bundle(path.resolve(__dirname, "..", "..")));
}
